#!/usr/bin/env bash
set -euo pipefail
[[ -d .git && -f pubspec.yaml && -f desktop/hyper_player/lib/main.dart ]] || { echo 'Run in your existing MaxPlayer repository root, after the Windows preview updates.' >&2; exit 1; }
python3 - <<'NATIVE_UI'
from pathlib import Path
import base64
files = {
'desktop/hyper_player/lib/main.dart': '',
'desktop/hyper_player/ANDROID_STYLE_UI.md': '',
}
for name, encoded in files.items():
    path = Path(name)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(base64.b64decode(encoded))
print('Native Windows Android-style UI applied. Android unchanged.')
NATIVE_UI
